const points = ref([])
const page = ref(1)
const hasMore = ref(true)
const isLoading = ref(false)

const fetchPoints = async () => {
  if (isLoading.value || (!hasMore.value && page.value > 1)) return
  isLoading.value = true
  try {
    const res = await apiPost('member.php', {
      mode: 'pointList',
      idnt_code: student.value?.idnt_code || sessionStorage.getItem('idnt_code'),
      page: page.value
    })

    if (res.result === 'SUCCESS' && Array.isArray(res.data)) {
      if (res.data.length < 10) {
        hasMore.value = false
      }
      points.value = [...points.value, ...res.data]
      page.value++
    } else {
      hasMore.value = false
    }
  } catch (e) {
    console.error(e)
    hasMore.value = false
  } finally {
    isLoading.value = false
  }
}

const refreshPoints = async () => {
  points.value = []
  page.value = 1
  hasMore.value = true
  await fetchPoints()
}



// 문자열에서 알레르기 번호만 추출
const extractAllergyNames = (text) => {
  const match = text.match(/\(([\d.,\s]+)\)/)
  if (!match) return []

  return match[1]
    .split(/[.,\s]+/)
    .map(Number)
    .filter(n => allergyMap[n])
    .map(n => allergyMap[n])
}



